        if 'chanops' in defaultops[0].keys():
            chanops = chanops + defaultops[0]['chanops']
    if 'inherits-from' in channeldata.keys():
        for x in channeldata['inherits-from']:
            y = channelparse(channel=x, cachedjson=chanopsjson)
