                    line_number_map["pc_jump_map"][pos] = "o"
                else:
                    line_number_map["pc_jump_map"][pos] = "i"
            else:
                line_number_map["pc_jump_map"][pos] = "-"
        elif item in ("JUMPI", "JUMPDEST"):
            line_number_map["pc_jump_map"][pos] = "-"
