class MercurialRepo(BaseRepo):
    bin_name = "hg"
    schemes = ("hg", "hg+http", "hg+https", "hg+file")
    def __init__(self, url, repo_dir, **kwargs):
        BaseRepo.__init__(self, url, repo_dir, **kwargs)
    def obtain(self):
        self.ensure_dir()
        self.run(["clone", "--noupdate", "-q", self.url, self.path])
        self.run(["update", "-q"])
