        return '''SiteConfig[{}]:
        download url: {}
        archive url:  {}
        public url:   {}
        metadata url: {}
        pastie class: {}
        '''.format(self.name, self.download_url, self.archive_url,
                self.public_url, self.metadata_url, self.pastie_classname)
