    @processor(Action.NoOp)
    async def no_op(params: models.IsNone):
        pass
    if debug:
        for action in Action:
            if action not in processors:
                raise ExecutionError(f"{action.value} does not have a processor.")
    async def process_action(action, value):
        self.last_action = action
        if debug and action not in ALLOWED_DEBUG_ACTIONS:
            return
        params = model_validator(action, value)
        try:
            processor_func = processors[action]
        except KeyError:
            raise ExecutionError(f"Unhandled action '{action.value}'.")
        await processor_func(params)
    last_cond_action_result = None
    for entry in self.actions:
        for enum, value in entry.items():
            enum = self._get_actions_enum(enum)
            if isinstance(enum, Action):
                try:
                    await process_action(enum, value)
                except StopExecution:
                    return bool(last_expel_action)
            elif isinstance(enum, Condition):
                _eval = await self._evaluate_conditions([{enum.value: value}],
                                                        cog=cog, user=user, message=message,
                                                        guild=guild, templates_vars=templates_vars,
                                                        debug=debug)
                last_cond_action_result = _eval[0]
            elif isinstance(enum, ConditionBlock):
                _eval = await self._evaluate_conditions_block(block=[{enum.value: value}],
                                                              cog=cog, user=user, message=message,
                                                              guild=guild, templates_vars=templates_vars,
                                                              debug=debug)
                last_cond_action_result = bool(_eval)
            elif isinstance(enum, ConditionalActionBlock):
                is_true = enum == ConditionalActionBlock.IfTrue and last_cond_action_result is True
                is_false = enum == ConditionalActionBlock.IfFalse and last_cond_action_result is False
                if is_true or is_false:
                    for raw_action in value:
                        for action, subvalue in raw_action.items():
                            action = self._get_actions_enum(action)
                            try:
                                await process_action(action, subvalue)
                            except StopExecution:
                                return bool(last_expel_action)
    return bool(last_expel_action)

def check_prereg_key(request: HttpRequest, confirmation_key: str) -> PreregistrationUser:
    """
    Checks if the Confirmation key is valid, returning the PreregistrationUser object in case of success
    and raising an appropriate ConfirmationKeyError otherwise.
    """
    confirmation_types = [
        Confirmation.USER_REGISTRATION,
        Confirmation.INVITATION,
        Confirmation.REALM_CREATION,
    ]
    prereg_user = get_object_from_key(confirmation_key, confirmation_types, mark_object_used=False)
    assert isinstance(prereg_user, PreregistrationUser)
    assert prereg_user.created_user is None
    return prereg_user
def accounts_register(
    request: HttpRequest,
    key: str = REQ(default=""),
    timezone: str = REQ(default="", converter=to_timezone_or_empty),
    from_confirmation: Optional[str] = REQ(default=None),
    form_full_name: Optional[str] = REQ("full_name", default=None),
    source_realm_id: Optional[int] = REQ(
        default=None, converter=to_converted_or_fallback(to_non_negative_int, None)
    ),
) -> HttpResponse:
    try:
        prereg_user = check_prereg_key(request, key)
    except ConfirmationKeyError as e:
        return render_confirmation_key_error(request, e)
    email = prereg_user.email
    realm_creation = prereg_user.realm_creation
    password_required = prereg_user.password_required
    role = prereg_user.invited_as
    if realm_creation:
        role = UserProfile.ROLE_REALM_OWNER
    try:
        validators.validate_email(email)
    except ValidationError:
        return render(request, "zerver/invalid_email.html", context={"invalid_email": True})
    if realm_creation:
        realm = None
    else:
        assert prereg_user.realm is not None
        if get_subdomain(request) != prereg_user.realm.string_id:
            return render_confirmation_key_error(
                request, ConfirmationKeyError(ConfirmationKeyError.DOES_NOT_EXIST)
            )
        realm = prereg_user.realm
        try:
